class Solution:
    def __init__(self, w):
        self.prefix_sums = []
        curr_sum = 0
        for x in w:
            curr_sum += x
            self.prefix_sums.append(curr_sum)
        self.total_sum = curr_sum

    def pickIndex(self):
        import random
        target = random.random() * self.total_sum
        import bisect
        return bisect.bisect_left(self.prefix_sums, target)

